{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-0TMJz0/src/merge.js","content":"import { computeChanges } from './lcs.js'

/**
 * Computes the diff3 merge structure for the three documents: an ordered
 * list of blocks covering the whole base document, each either a stable
 * span of base lines or a merged region (resolved to one side, to both, or
 * a conflict).
 */
export function buildMerge(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = computeChanges(base, theirs).map(c => ({ ...c, side: 'theirs' }))

  const combined = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    return a.side === b.side ? 0 : a.side === 'mine' ? -1 : 1
  })

  const regions = []
  for (const change of combined) {
    const current = regions[regions.length - 1]
    if (current && change.baseStart <= current.end) {
      current.end = Math.max(current.end, change.baseEnd)
      current.changes.push(change)
    } else {
      regions.push({ start: change.baseStart, end: change.baseEnd, changes: [change] })
    }
  }

  const blocks = []
  let pos = 0
  for (const region of regions) {
    if (region.start > pos) blocks.push({ type: 'stable', start: pos, end: region.start })
    blocks.push({ type: 'region', ...resolveRegion(region, mine, base, theirs) })
    pos = region.end
  }
  if (pos < base.length) blocks.push({ type: 'stable', start: pos, end: base.length })

  return blocks
}

/** Extracts the lines a side contributes to a region, per the task's rules. */
function sideLines(changes, region, sideDoc, baseDoc) {
  if (changes.length === 0) return baseDoc.slice(region.start, region.end)
  const first = changes[0]
  const last = changes[changes.length - 1]
  const leadGap = first.baseStart - region.start
  const trailGap = region.end - last.baseEnd
  return sideDoc.slice(first.sideStart - leadGap, last.sideEnd + trailGap)
}

function sameLines(a, b) {
  return a.length === b.length && a.every((line, i) => line === b[i])
}

function resolveRegion(region, mine, base, theirs) {
  const mineChanges = region.changes.filter(c => c.side === 'mine')
  const theirsChanges = region.changes.filter(c => c.side === 'theirs')

  const mineLines = sideLines(mineChanges, region, mine, base)
  const baseLines = base.slice(region.start, region.end)
  const theirsLines = sideLines(theirsChanges, region, theirs, base)

  if (sameLines(mineLines, theirsLines)) return { resolved: 'both', lines: mineLines }
  if (sameLines(mineLines, baseLines)) return { resolved: 'theirs', lines: theirsLines }
  if (sameLines(theirsLines, baseLines)) return { resolved: 'mine', lines: mineLines }
  return { resolved: 'conflict', mineLines, baseLines, theirsLines }
}
"}

