{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-0TMJz0/src/format.js","content":"/**
 * Renders a diff3 merge's blocks (from {@link buildMerge}) into the output
 * text for each of the CLI's three modes. Each renderer returns
 * `{ text, conflict }`, where `conflict` says whether any conflict was
 * written.
 */

function linesOf(lines) {
  return lines.map(line => `${line}\n`).join('')
}

/** Renders `merge` output: resolved lines, with full three-way conflict markers. */
export function renderMerge(blocks, base) {
  return render(blocks, base, true)
}

/** Renders `merge2` output: like `merge`, but conflicts omit the base section. */
export function renderMerge2(blocks, base) {
  return render(blocks, base, false)
}

function render(blocks, base, includeBase) {
  let text = ''
  let conflict = false
  for (const block of blocks) {
    if (block.type === 'stable') {
      text += linesOf(base.slice(block.start, block.end))
    } else if (block.resolved === 'conflict') {
      conflict = true
      text += '<<<<<<< mine\n'
      text += linesOf(block.mineLines)
      if (includeBase) {
        text += '||||||| base\n'
        text += linesOf(block.baseLines)
      }
      text += '=======\n'
      text += linesOf(block.theirsLines)
      text += '>>>>>>> theirs\n'
    } else {
      text += linesOf(block.lines)
    }
  }
  return { text, conflict }
}

/** Renders `regions` output: one summary line per block. */
export function renderRegions(blocks, base) {
  let text = ''
  let conflict = false
  for (const block of blocks) {
    if (block.type === 'stable') {
      text += `stable ${block.end - block.start}\n`
    } else if (block.resolved === 'conflict') {
      conflict = true
      text += `conflict mine=${block.mineLines.length} base=${block.baseLines.length} theirs=${block.theirsLines.length}\n`
    } else {
      text += `${block.resolved} ${block.lines.length}\n`
    }
  }
  return { text, conflict }
}
"}

