{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-0TMJz0/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { parseDocuments, InputFormatError } from './parse.js'
import { buildMerge } from './merge.js'
import { renderMerge, renderMerge2, renderRegions } from './format.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'merge' && mode !== 'merge2' && mode !== 'regions') {
    fail('usage: cli.js merge|merge2|regions')
    return
  }

  const input = readStdin()
  let mine, base, theirs
  try {
    ;[mine, base, theirs] = parseDocuments(input)
  } catch (err) {
    if (err instanceof InputFormatError) {
      fail(err.message)
      return
    }
    throw err
  }

  const blocks = buildMerge(mine, base, theirs)
  const { text, conflict } =
    mode === 'merge' ? renderMerge(blocks, base) : mode === 'merge2' ? renderMerge2(blocks, base) : renderRegions(blocks, base)

  process.stdout.write(text)
  process.exit(conflict ? 1 : 0)
}

main()
"}

