{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-6g0mko/src/format.js","content":"/**
 * Render the `rounds` output: one `round K: ` line per round, each followed
 * by an `eliminated <name>` line when that round eliminated someone, and a
 * final `winner <name>` or `no winner` line.
 *
 * @param {{rounds: {counts: Map<string, bigint>, exhausted: bigint, eliminated: string|null}[], winner: string|null}} result
 * @returns {string}
 */
export function formatRounds(result) {
  const lines = []
  result.rounds.forEach((round, index) => {
    const entries = [...round.counts].sort((a, b) => {
      if (a[1] !== b[1]) return a[1] > b[1] ? -1 : 1
      return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
    })
    const parts = entries.map(([name, votes]) => `${name}=${votes}`)
    parts.push(`exhausted=${round.exhausted}`)
    lines.push(`round ${index + 1}: ${parts.join(' ')}`)
    if (round.eliminated !== null) {
      lines.push(`eliminated ${round.eliminated}`)
    }
  })
  lines.push(result.winner === null ? 'no winner' : `winner ${result.winner}`)
  return lines.join('\n') + '\n'
}

/**
 * Render the `tally` output: the round count and the outcome.
 *
 * @param {{rounds: unknown[], winner: string|null}} result
 * @returns {string}
 */
export function formatTally(result) {
  const lines = [`rounds ${result.rounds.length}`]
  lines.push(result.winner === null ? 'no winner' : `winner ${result.winner}`)
  return lines.join('\n') + '\n'
}
"}

