{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-6g0mko/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parseElection } from './parser.js'
import { runElection } from './election.js'
import { formatRounds, formatTally } from './format.js'
import { ElectionError } from './errors.js'

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }

  const input = readFileSync(0, 'utf8')

  let output
  try {
    const election = parseElection(input)
    const result = runElection(election)
    output = mode === 'rounds' ? formatRounds(result) : formatTally(result)
  } catch (err) {
    if (err instanceof ElectionError) {
      const prefix = err.line === null ? 'error: ' : `error: line ${err.line}: `
      process.stderr.write(`${prefix}${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  process.stdout.write(output)
  process.exit(0)
}

main()
"}

