{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-90sbQP/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { parseGraph } from './parse.js'
import { detectCycle, computeSchedule, packWorkers } from './graph.js'
import { GraphError } from './errors.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9][0-9]*$/

function fail(message, exitCode) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(exitCode)
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]

  let workerCount
  if (mode === 'waves' || mode === 'explain') {
    if (args.length !== 1) fail(USAGE, 2)
  } else if (mode === 'pack') {
    if (args.length !== 2) fail(USAGE, 2)
    if (!WORKERS_RE.test(args[1])) fail('workers must be a positive integer', 2)
    workerCount = parseInt(args[1], 10)
  } else {
    fail(USAGE, 2)
  }

  const input = readFileSync(0, 'utf8')

  let tasks
  let deps
  try {
    ;({ tasks, deps } = parseGraph(input))
    detectCycle(tasks, deps)
  } catch (error) {
    if (error instanceof GraphError) fail(error.message, error.exitCode)
    throw error
  }

  const names = [...tasks.keys()].sort()

  if (mode === 'waves') {
    const { finish, depth } = computeSchedule(tasks, deps)
    const byDepth = []
    for (const name of names) {
      const d = depth.get(name)
      ;(byDepth[d] ??= []).push(name)
    }
    let output = ''
    for (let k = 0; k < byDepth.length; k++) {
      output += `wave ${k}: ${byDepth[k].join(' ')}\n`
    }
    const total = names.length === 0 ? 0 : Math.max(...names.map((name) => finish.get(name)))
    output += `total ${total}\n`
    process.stdout.write(output)
  } else if (mode === 'explain') {
    const { start, finish, depth } = computeSchedule(tasks, deps)
    let output = ''
    for (const name of names) {
      output += `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}\n`
    }
    const total = names.length === 0 ? 0 : Math.max(...names.map((name) => finish.get(name)))
    output += `total ${total}\n`
    process.stdout.write(output)
  } else {
    const { workers, makespan } = packWorkers(tasks, deps, workerCount)
    let output = ''
    for (let i = 0; i < workers.length; i++) {
      const runs = workers[i].map((run) => ` ${run.name}@${run.start}-${run.finish}`).join('')
      output += `worker ${i}:${runs}\n`
    }
    output += `makespan ${makespan}\n`
    process.stdout.write(output)
  }
}

main()
