const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

// Two-character punctuators must be tried before their single-character
// prefixes, so this list is ordered longest first.
const PUNCTS = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

export class LexError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

function isLetter(cp) {
  return cp !== undefined && /[A-Za-z]/.test(cp)
}

function isDigit(cp) {
  return cp !== undefined && cp >= '0' && cp <= '9'
}

function isHexDigit(cp) {
  return cp !== undefined && /[0-9A-Fa-f]/.test(cp)
}

