 * The scanner: turns UTF-8 source text into a stream of tokens, tracking
 * line/column positions per the language's tab and newline rules.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

export class ScanError extends Error {
  constructor(pos, reason) {
    super(reason)
    this.line = pos.line
    this.col = pos.col
    this.reason = reason
  }
}

function isDecimalDigit(c) {
  return c >= '0' && c <= '9'
}

function isHexDigit(c) {
  return c !== undefined && /^[0-9a-fA-F]$/.test(c)
}

function isBinDigit(c) {
  return c === '0' || c === '1'
}

function isOctDigit(c) {
  return c >= '0' && c <= '7'
}

function isIdentStart(c) {
  return c !== undefined && /^[\p{L}_]$/u.test(c)
}

function isIdentContinue(c) {
  return c !== undefined && /^[\p{L}0-9_]$/u.test(c)
}

class Scanner {
  constructor(input) {
    this.chars = Array.from(input)
    this.i = 0
    this.line = 1
    this.col = 1
  }

  eof() {
    return this.i >= this.chars.length
  }

  current() {
    return this.chars[this.i]
  }

  peek(n = 1) {
    return this.chars[this.i + n]
  }

  pos() {
    return { line: this.line, col: this.col }
  }

  advance() {
    const c = this.chars[this.i]
    this.i++
    if (c === '\n') {
      this.line++
      this.col = 1
    } else if (c === '\t') {
      this.col = Math.floor((this.col - 1) / 4) * 4 + 5
    } else {
      this.col++
    }
  }
}

function skipLineComment(s) {
  s.advance()
  s.advance()
  while (!s.eof() && s.current() !== '\n') s.advance()
}

function skipBlockComment(s) {
  const start = s.pos()
  s.advance()
  s.advance()
  let depth = 1
  while (depth > 0) {
    if (s.eof()) throw new ScanError(start, 'unterminated block comment')
    if (s.current() === '/' && s.peek() === '*') {
      s.advance()
      s.advance()
      depth++
      continue
    }
    if (s.current() === '*' && s.peek() === '/') {
      s.advance()
      s.advance()
      depth--
      continue
    }
    s.advance()
  }
}

function skipTrivia(s) {
  while (!s.eof()) {
    const c = s.current()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
