        const h2 = s.peek(2)
        if (isHexDigit(h1) && isHexDigit(h2)) {
          value += String.fromCharCode(parseInt(h1 + h2, 16))
          advanceN(s, 3)
        } else {
          throw new ScanError(bsPos, 'invalid escape \\x')
        }
      } else if (sel === 'u') {
        if (s.peek(1) === '{') {
          let j = 2
          let hex = ''
          while (isHexDigit(s.peek(j))) {
            hex += s.peek(j)
            j++
          }
          const cp = hex.length > 0 ? parseInt(hex, 16) : NaN
          if (hex.length > 0 && s.peek(j) === '}' && cp <= 0x10ffff) {
            value += String.fromCodePoint(cp)
            advanceN(s, j + 1)
          } else {
            throw new ScanError(bsPos, 'invalid escape \\u')
          }
        } else {
          throw new ScanError(bsPos, 'invalid escape \\u')
        }
      } else {
        throw new ScanError(bsPos, `invalid escape \\${sel}`)
      }
    } else {
      value += c
      s.advance()
    }
  }
  return { kind: 'string', line: start.line, col: start.col, text: JSON.stringify(value) }
}

function scanRawString(s) {
  const start = s.pos()
  s.advance()
  s.advance()
  let value = ''
  for (;;) {
    if (s.eof()) throw new ScanError(start, 'unterminated string')
    const c = s.current()
    if (c === '"') {
      s.advance()
      break
    }
    value += c
    s.advance()
  }
