  if (PUNCT1.includes(c1)) {
    s.advance()
    return { kind: 'punct', line: start.line, col: start.col, text: c1 }
  }
  return null
}

export function* scan(input) {
  const s = new Scanner(input)
  for (;;) {
    skipTrivia(s)
    if (s.eof()) return
    const start = s.pos()
    const c = s.current()
    if (isDecimalDigit(c)) {
      yield scanNumber(s)
      continue
    }
    if (c === 'r' && s.peek() === '"') {
      yield scanRawString(s)
      continue
    }
    if (isIdentStart(c)) {
      yield scanIdentifier(s)
      continue
    }
    if (c === '"') {
      yield scanString(s)
      continue
    }
    const punct = matchPunct(s)
    if (punct) {
      yield punct
      continue
    }
    throw new ScanError(start, `unexpected character ${c}`)
  }
}
