/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { scan, ScanError } from './scanner.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    fail('usage: cli.js tokens|stats')
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')

  let output
  try {
    if (mode === 'tokens') {
      const lines = []
      for (const token of scan(input)) {
        lines.push(`${token.line}:${token.col} ${token.kind} ${token.text}\n`)
      }
      output = lines.join('')
    } else {
      const counts = Object.fromEntries(STAT_KINDS.map((k) => [k, 0]))
      let total = 0
      for (const token of scan(input)) {
        counts[token.kind]++
        total++
      }
      output = STAT_KINDS.map((k) => `${k} ${counts[k]}\n`).join('') + `total ${total}\n`
    }
  } catch (err) {
    if (err instanceof ScanError) {
      fail(`${err.line}:${err.col}: ${err.reason}`)
    }
    throw err
  }

  process.stdout.write(output)
}

main()
"}

