{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-AhWASp/src/lexer.js","content":"/**
 * Scanner for the small language described in the task prompt. `scan` turns
 * a source string into an array of tokens or throws a `LexError` at the
 * first character the grammar rejects.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

export class LexError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHexDigit = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isIdentStart = (c) => c !== undefined && (isLetter(c) || c === '_')
const isIdentPart = (c) => c !== undefined && (isLetter(c) || isDigit(c) || c === '_')
const isTrailingChar = isIdentPart

function tabStop(col) {
  return (Math.floor((col - 1) / 4) + 1) * 4 + 1
}

export function scan(source) {
  const chars = Array.from(source)
  const n = chars.length
  let i = 0
  let line = 1
  let col = 1
  const tokens = []

  function advance() {
    const ch = chars[i]
    const posLine = line
    const posCol = col
    i++
    if (ch === '\n') {
      line++
      col = 1
    } else if (ch === '\t') {
      col = tabStop(col)
    } else {
      col++
    }
    return { ch, line: posLine, col: posCol }
  }

  function scanDigitRun(pred) {
    for (;;) {
      if (pred(chars[i])) {
        advance()
      } else if (chars[i] === '_' && pred(chars[i + 1])) {
        advance()
      } else {
        break
      }
    }
  }

  function scanNumber(startPos) {
    const start = i
    let ok

    if (chars[i] === '0' && /^[xXbBoO]$/.test(chars[i + 1] || '')) {
      const prefixChar = chars[i + 1].toLowerCase()
      advance()
      advance()
      const pred = prefixChar === 'x' ? isHexDigit : prefixChar === 'b' ? (c) => c === '0' || c === '1' : (c) => c !== undefined && c >= '0' && c <= '7'
      if (pred(chars[i])) {
        scanDigitRun(pred)
        ok = true
      } else {
        ok = false
      }
    } else {
      scanDigitRun(isDigit)
      if (chars[i] === '.' && isDigit(chars[i + 1])) {
        advance()
        scanDigitRun(isDigit)
      }
      if (chars[i] === 'e' || chars[i] === 'E') {
        if (isDigit(chars[i + 1])) {
          advance()
          scanDigitRun(isDigit)
        } else if ((chars[i + 1] === '+' || chars[i + 1] === '-') && isDigit(chars[i + 2])) {
          advance()
          advance()
          scanDigitRun(isDigit)
        }
      }
      ok = true
    }

    if (!ok || isTrailingChar(chars[i])) {
      while (isTrailingChar(chars[i])) advance()
      const text = chars.slice(start, i).join('')
      throw new LexError(startPos.line, startPos.col, `invalid number ${text}`)
    }

    const text = chars.slice(start, i).join('')
    tokens.push({ line: startPos.line, col: startPos.col, kind: 'number', text })
  }

  function scanIdent(startPos) {
    const start = i
    while (isIdentPart(chars[i])) advance()
    const text = chars.slice(start, i).join('')
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    tokens.push({ line: startPos.line, col: startPos.col, kind, text })
  }

  function scanString(startPos) {
    advance() // opening quote
    let value = ''
    for (;;) {
      if (i >= n) throw new LexError(startPos.line, startPos.col, 'unterminated string')
      const ch = chars[i]
      if (ch === '"') {
        advance()
        break
      }
      if (ch === '\n') {
        throw new LexError(line, col, 'newline in string')
      }
      if (ch === '\\') {
        const bsLine = line
        const bsCol = col
        advance() // backslash
        if (i >= n) throw new LexError(startPos.line, startPos.col, 'unterminated string')
        const ec = chars[i]
        if (ec === 'n') {
          value += '\n'
          advance()
        } else if (ec === 't') {
          value += '\t'
          advance()
        } else if (ec === 'r') {
          value += '\r'
          advance()
        } else if (ec === '\\') {
          value += '\\'
          advance()
        } else if (ec === '"') {
          value += '"'
          advance()
        } else if (ec === '0') {
          value += '\0'
          advance()
        } else if (ec === 'x') {
          advance() // x
          if (i + 1 >= n) throw new LexError(startPos.line, startPos.col, 'unterminated string')
          if (isHexDigit(chars[i]) && isHexDigit(chars[i + 1])) {
            const hh = chars[i] + chars[i + 1]
            value += String.fromCharCode(parseInt(hh, 16))
            advance()
            advance()
          } else {
            throw new LexError(bsLine, bsCol, 'invalid escape \\x')
          }
        } else if (ec === 'u') {
          advance() // u
          if (i >= n) throw new LexError(startPos.line, startPos.col, 'unterminated string')
          if (chars[i] !== '{') throw new LexError(bsLine, bsCol, 'invalid escape \\u')
          advance() // {
          let hexDigits = ''
          for (;;) {
            if (i >= n) throw new LexError(startPos.line, startPos.col, 'unterminated string')
            if (isHexDigit(chars[i])) {
              hexDigits += chars[i]
              advance()
            } else {
              break
            }
          }
          if (hexDigits.length === 0) throw new LexError(bsLine, bsCol, 'invalid escape \\u')
          if (chars[i] !== '}') throw new LexError(bsLine, bsCol, 'invalid escape \\u')
          advance() // }
          const cp = parseInt(hexDigits, 16)
          if (cp > 0x10ffff) throw new LexError(bsLine, bsCol, 'invalid escape \\u')
          value += String.fromCodePoint(cp)
        } else {
          throw new LexError(bsLine, bsCol, `invalid escape \\${ec}`)
        }
      } else {
        value += ch
        advance()
      }
    }
    tokens.push({ line: startPos.line, col: startPos.col, kind: 'string', text: value })
  }

  function scanRawString(startPos) {
    advance() // r
    advance() // opening quote
    let value = ''
    for (;;) {
      if (i >= n) throw new LexError(startPos.line, startPos.col, 'unterminated string')
      const ch = chars[i]
      if (ch === '"') {
        advance()
        break
      }
      value += ch
      advance()
    }
    tokens.push({ line: startPos.line, col: startPos.col, kind: 'rawstring', text: value })
  }

  while (i < n) {
    const ch = chars[i]

    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
      advance()
      continue
    }

    if (ch === '/' && chars[i + 1] === '/') {
      while (i < n && chars[i] !== '\n') advance()
      continue
    }

    if (ch === '/' && chars[i + 1] === '*') {
      const startLine = line
      const startCol = col
      advance()
      advance()
      let depth = 1
      while (depth > 0) {
        if (i >= n) throw new LexError(startLine, startCol, 'unterminated block comment')
        if (chars[i] === '/' && chars[i + 1] === '*') {
          advance()
          advance()
          depth++
        } else if (chars[i] === '*' && chars[i + 1] === '/') {
          advance()
          advance()
          depth--
        } else {
          advance()
        }
      }
      continue
    }

    const startPos = { line, col }

    if (ch === 'r' && chars[i + 1] === '"') {
      scanRawString(startPos)
      continue
    }

    if (isIdentStart(ch)) {
      scanIdent(startPos)
      continue
    }

    if (isDigit(ch)) {
      scanNumber(startPos)
      continue
    }

    if (ch === '"') {
      scanString(startPos)
      continue
    }

    const two = ch + (chars[i + 1] || '')
    if (TWO_CHAR_PUNCT.has(two)) {
      advance()
      advance()
      tokens.push({ line: startPos.line, col: startPos.col, kind: 'punct', text: two })
      continue
    }

    if (ONE_CHAR_PUNCT.has(ch)) {
      advance()
      tokens.push({ line: startPos.line, col: startPos.col, kind: 'punct', text: ch })
      continue
    }

    throw new LexError(startPos.line, startPos.col, `unexpected character ${ch}`)
  }

  return tokens
}
"}

