  function scanNumber(startPos) {
    const start = i
    let ok

    if (chars[i] === '0' && /^[xXbBoO]$/.test(chars[i + 1] || '')) {
      const prefixChar = chars[i + 1].toLowerCase()
      advance()
      advance()
      const pred = prefixChar === 'x' ? isHexDigit : prefixChar === 'b' ? (c) => c === '0' || c === '1' : (c) => c !== undefined && c >= '0' && c <= '7'
      if (pred(chars[i])) {
        scanDigitRun(pred)
        ok = true
      } else {
        ok = false
      }
    } else {
      scanDigitRun(isDigit)
      if (chars[i] === '.' && isDigit(chars[i + 1])) {
        advance()
        scanDigitRun(isDigit)
      }
      if (chars[i] === 'e' || chars[i] === 'E') {
        if (isDigit(chars[i + 1])) {
          advance()
          scanDigitRun(isDigit)
        } else if ((chars[i + 1] === '+' || chars[i + 1] === '-') && isDigit(chars[i + 2])) {
          advance()
          advance()
          scanDigitRun(isDigit)
        }
      }
      ok = true
    }

    if (!ok || isTrailingChar(chars[i])) {
      while (isTrailingChar(chars[i])) advance()
      const text = chars.slice(start, i).join('')
      throw new LexError(startPos.line, startPos.col, `invalid number ${text}`)
    }

    const text = chars.slice(start, i).join('')
    tokens.push({ line: startPos.line, col: startPos.col, kind: 'number', text })
  }

