    const start = i
    while (isIdentPart(chars[i])) advance()
    const text = chars.slice(start, i).join('')
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    tokens.push({ line: startPos.line, col: startPos.col, kind, text })
