          advance()
        } else if (ec === 't') {
          value += '\t'
          advance()
        } else if (ec === 'r') {
          value += '\r'
          advance()
        } else if (ec === '\\') {
          value += '\\'
          advance()
        } else if (ec === '"') {
          value += '"'
          advance()
        } else if (ec === '0') {
          value += '\0'
          advance()
        } else if (ec === 'x') {
          advance() // x
