          for (;;) {
            if (i >= n) throw new LexError(startPos.line, startPos.col, 'unterminated string')
            if (isHexDigit(chars[i])) {
              hexDigits += chars[i]
              advance()
            } else {
              break
            }
          }
          if (hexDigits.length === 0) throw new LexError(bsLine, bsCol, 'invalid escape \\u')
          if (chars[i] !== '}') throw new LexError(bsLine, bsCol, 'invalid escape \\u')
          advance() // }
          const cp = parseInt(hexDigits, 16)
          if (cp > 0x10ffff) throw new LexError(bsLine, bsCol, 'invalid escape \\u')
