  const mode = args[0]
  if (args.length !== 1 || (mode !== 'tokens' && mode !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const source = readStdin()

  let tokens
  try {
    tokens = scan(source)
  } catch (err) {
    if (err instanceof LexError) {
      process.stderr.write(`error: ${err.line}:${err.col}: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  let output = ''
  if (mode === 'tokens') {
    for (const tok of tokens) {
      const body = tok.kind === 'string' || tok.kind === 'rawstring' ? JSON.stringify(tok.text) : tok.text
      output += `${tok.line}:${tok.col} ${tok.kind} ${body}\n`
    }
  } else {
    const counts = Object.fromEntries(STAT_KINDS.map((k) => [k, 0]))
    for (const tok of tokens) counts[tok.kind]++
    for (const k of STAT_KINDS) output += `${k} ${counts[k]}\n`
    output += `total ${tokens.length}\n`
  }

  process.stdout.write(output)
  process.exit(0)
}

main()
"}

