/**
 * Normalize a label: trim it, collapse runs of whitespace to one space, and lowercase it.
 * @param {string} label - the label as written.
 * @returns {string} the normalized label.
 */
export function normalizeLabel(label) {
  return label.trim().replace(/\s+/gu, ' ').toLowerCase()
}

const DEFINITION = /^\[([^\]]*)\]:\s+(\S.*)$/u

/**
 * Read one line as a link definition.
 * @param {string} trimmed - the line, already trimmed.
 * @returns {{label: string, url: string}|undefined} the normalized label and url, or undefined when the line is not a definition.
 */
export function readDefinition(trimmed) {
  const match = DEFINITION.exec(trimmed)
  if (match === null) return undefined
  return { label: normalizeLabel(match[1]), url: match[2] }
}
"}

