/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parse.js'
import { runElection } from './election.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const fs = require ? null : null // placeholder, replaced below
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    fail('usage: cli.js rounds|tally')
    return
  }
  const mode = args[0]

  const chunks = []
  for await (const chunk of process.stdin) {
    chunks.push(chunk)
  }
  const input = Buffer.concat(chunks.map((c) => Buffer.from(c))).toString('utf8')

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      const location = err.line === null ? '' : `line ${err.line}: `
      fail(`${location}${err.message}`)
      return
    }
    throw err
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)

  const output = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      const parts = round.counts.map((c) => `${c.name}=${c.votes}`)
      parts.push(`exhausted=${round.exhausted}`)
      output.push(`round ${index + 1}: ${parts.join(' ')}`)
      if (round.eliminated !== null) {
        output.push(`eliminated ${round.eliminated}`)
      }
    })
  } else {
    output.push(`rounds ${rounds.length}`)
  }
  output.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(output.join('\n') + '\n')
  process.exit(0)
}

main()
"}

