import { BlockError, headings, parse, render, splitLines } from './block.js'
import { DEFINITION, normalizeLabel } from './labels.js'

const USAGE = 'usage: cli.js html|outline|defs [<definitions>]'
const MODES = ['html', 'outline', 'defs']

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/**
 * Read a definitions file: one definition per line, blank lines and `#` comments ignored.
 * @param {string} path - the file's path, as named on the command line.
 * @returns {Map<string, {url: string, source: string}>} its definitions.
 */
function readDefinitionsFile(path) {
  let content
  try {
    content = readFileSync(path, 'utf8')
  } catch {
    fail(`cannot read definitions ${path}`)
    return new Map()
  }
  const definitions = new Map()
  const lines = splitLines(content)
  for (let index = 0; index < lines.length; index += 1) {
    const line = index + 1
    const trimmed = lines[index].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const match = DEFINITION.exec(trimmed)
    if (match === null) {
      fail(`${path}: line ${line}: expected [label]: <url>`)
      return new Map()
    }
    const label = normalizeLabel(match[1])
    if (definitions.has(label)) {
      fail(`${path}: line ${line}: label ${label} is defined twice`)
      return new Map()
    }
    definitions.set(label, { url: match[2], source: 'file' })
  }
  return definitions
}

function main() {
  const argv = process.argv.slice(2)
  const mode = argv[0]
  if (!MODES.includes(mode) || argv.length < 1 || argv.length > 2) {
    fail(USAGE)
    return
  }

  const fileDefinitions = argv.length === 2 ? readDefinitionsFile(argv[1]) : new Map()

  let parsed
  try {
    parsed = parse(splitLines(readFileSync(0, 'utf8')), fileDefinitions)
  } catch (error) {
    if (!(error instanceof BlockError)) throw error
    fail(`line ${error.line}: ${error.message}`)
    return
  }

  if (mode === 'html') {
    process.stdout.write(render(parsed.blocks, parsed.definitions))
    return
  }
  if (mode === 'outline') {
    process.stdout.write(headings(parsed.blocks).map(one => `${one.level} ${one.text}\n`).join(''))
    return
  }
  const rows = [...parsed.definitions.entries()].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  const lines = rows.map(([label, definition]) => `${label} ${definition.url} ${definition.source}\n`)
  lines.push(`total ${rows.length}\n`)
  process.stdout.write(lines.join(''))
}

