    records.push({ line: i + 1, words: trimmed.split(/\s+/) })
  }
  return records
}

/**
 * Runs a limiter file's events and returns them in log order alongside the
 * policies' final tallies. Throws `LimiterError` on any parse or
 * declaration failure.
 */
export function simulate(text) {
  const records = tokenize(text)
  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  const results = []
  const totals = new Map()
  let lastTick = null
  let eventsStarted = false

  const totalsFor = (key) => {
    let t = totals.get(key)
    if (t === undefined) {
      t = { allowed: 0, denied: 0 }
      totals.set(key, t)
    }
    return t
  }

  for (const { line, words } of records) {
    const directive = words[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (eventsStarted) fail(line, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (words.length !== 5) fail(line, 'expected bucket <name> <capacity> <refill> <per>')
      const name = requireName(line, words[1], 'policy name')
      if (policies.has(name)) fail(line, `policy ${name} is declared twice`)
      const capacity = parseField(line, words[2], 'capacity', 1n)
      const refill = parseField(line, words[3], 'refill', 0n)
      const per = parseField(line, words[4], 'per', 1n)
      policies.set(name, new TokenBucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (words.length !== 4) fail(line, 'expected window <name> <limit> <span>')
      const name = requireName(line, words[1], 'policy name')
      if (policies.has(name)) fail(line, `policy ${name} is declared twice`)
      const limit = parseField(line, words[2], 'limit', 0n)
      const span = parseField(line, words[3], 'span', 1n)
      policies.set(name, new SlidingWindow(limit, span))
    } else if (directive === 'route') {
      if (words.length < 3) fail(line, 'expected route <prefix> <policy>...')
      const prefix = requireName(line, words[1], 'route prefix')
      if (routePrefixes.has(prefix)) fail(line, `prefix ${prefix} is routed twice`)
      const names = words.slice(2)
      for (const name of names) {
        if (!policies.has(name)) fail(line, `unknown policy ${name}`)
      }
      routePrefixes.add(prefix)
      routes.push({ prefix, names })
    } else if (directive === 'event') {
      if (words.length !== 3) fail(line, 'expected event <tick> <key>')
      const tick = parseField(line, words[1], 'tick', 0n)
      const key = requireName(line, words[2], 'key')
      if (lastTick !== null && tick < lastTick) fail(line, `tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      eventsStarted = true

      let route = null
      for (const candidate of routes) {
        if (key.startsWith(candidate.prefix)) {
          if (route === null || candidate.prefix.length > route.prefix.length) route = candidate
        }
      }

      const tally = totalsFor(key)
      if (route === null) {
        results.push({ line, tick, key, allowed: true, deniedBy: null })
        tally.allowed++
        continue
      }

      const policyList = route.names.map((name) => policies.get(name))
      for (const policy of policyList) policy.advance(key, tick)

      let deniedBy = null
      for (let i = 0; i < policyList.length; i++) {
        if (!policyList[i].allows(key)) {
          deniedBy = route.names[i]
          break
        }
      }

      if (deniedBy === null) {
        for (const policy of policyList) policy.record(key, tick)
        tally.allowed++
      } else {
        tally.denied++
      }
      results.push({ line, tick, key, allowed: deniedBy === null, deniedBy })
    } else {
      fail(line, `unknown directive ${directive}`)
    }
  }

  return { results, totals }
}
"}

