/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { parseUri, normalizeComponents, resolveComponents, serialize, UriError } from './uri.js'

function readStdin() {
  const chunks = []
  return new Promise((resolve, reject) => {
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

/** Splits stdin into records: one per line, dropping the empty tail a trailing newline leaves. */
function splitRecords(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function normalizeLine(line) {
  const parsed = parseUri(line)
  return serialize(normalizeComponents(parsed))
}

function resolveLine(line) {
  const spaceIdx = line.indexOf(' ')
  if (spaceIdx === -1) throw new UriError('expected a base and a reference')
  const base = parseUri(line.slice(0, spaceIdx))
  if (base.scheme === null) throw new UriError('the base has no scheme')
  const ref = parseUri(line.slice(spaceIdx + 1))
  return serialize(normalizeComponents(resolveComponents(base, ref)))
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
    return
  }
  const mode = args[0]
  const input = await readStdin()
  const records = splitRecords(input)

  const results = []
  for (let i = 0; i < records.length; i++) {
    const lineNumber = i + 1
    try {
      results.push(mode === 'normalize' ? normalizeLine(records[i]) : resolveLine(records[i]))
    } catch (err) {
      if (err instanceof UriError) {
        process.stderr.write(`error: line ${lineNumber}: ${err.message}\n`)
        process.exit(2)
        return
      }
      throw err
    }
  }

  process.stdout.write(results.map((r) => `${r}\n`).join(''))
  process.exit(0)
}

main()
"}

