{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-HghexT/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { normalizeReference, resolveReference, ParseError } from './uri.js'

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'normalize' && mode !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const input = readStdin()
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const results = []
  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const line = lines[i]
    try {
      if (mode === 'normalize') {
        results.push(normalizeReference(line))
      } else {
        const spaceIdx = line.indexOf(' ')
        if (spaceIdx === -1) {
          throw new ParseError('expected a base and a reference')
        }
        const base = line.slice(0, spaceIdx)
        const ref = line.slice(spaceIdx + 1)
        results.push(resolveReference(base, ref))
      }
    } catch (err) {
      if (err instanceof ParseError) {
        process.stderr.write(`error: line ${lineNumber}: ${err.message}\n`)
        process.exit(2)
      }
      throw err
    }
  }

  process.stdout.write(results.map((line) => line + '\n').join(''))
  process.exit(0)
}

main()
"}

