{"file_path":"src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies. Produces an AST or null when
 * the token stream does not belong to the formula grammar.
 *
 * Precedence, loosest first: comparisons, then `+`/`-`, then `*`/`/`, then
 * `^` (right-associative), then a leading `-`/`+` (binds tighter than `^`).
 * A range (`A1:B3`) is only accepted directly as a function call argument.
 */

import { tokenize } from './lexer.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  next() {
    return this.tokens[this.pos++]
  }

  atEnd() {
    return this.pos >= this.tokens.length
  }

  parseFormula() {
    const expr = this.parseComparison()
    if (expr === null) return null
    if (!this.atEnd()) return null
    return expr
  }

  parseComparison() {
    let left = this.parseAdditive()
    if (left === null) return null
    for (;;) {
      const t = this.peek()
      if (t && t.type === 'op' && COMPARISON_OPS.has(t.value)) {
        this.next()
        const right = this.parseAdditive()
        if (right === null) return null
        left = { type: 'binop', op: t.value, left, right }
      } else {
        return left
      }
    }
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    if (left === null) return null
    for (;;) {
      const t = this.peek()
      if (t && t.type === 'op' && (t.value === '+' || t.value === '-')) {
        this.next()
        const right = this.parseMultiplicative()
        if (right === null) return null
        left = { type: 'binop', op: t.value, left, right }
      } else {
        return left
      }
    }
  }

  parseMultiplicative() {
    let left = this.parsePower()
    if (left === null) return null
    for (;;) {
      const t = this.peek()
      if (t && t.type === 'op' && (t.value === '*' || t.value === '/')) {
        this.next()
        const right = this.parsePower()
        if (right === null) return null
        left = { type: 'binop', op: t.value, left, right }
      } else {
        return left
      }
    }
  }

  parsePower() {
    const base = this.parseUnary()
    if (base === null) return null
    const t = this.peek()
    if (t && t.type === 'op' && t.value === '^') {
      this.next()
      const exponent = this.parsePower()
      if (exponent === null) return null
      return { type: 'binop', op: '^', left: base, right: exponent }
    }
    return base
  }

  parseUnary() {
    const t = this.peek()
    if (t && t.type === 'op' && (t.value === '+' || t.value === '-')) {
      this.next()
      const operand = this.parseUnary()
      if (operand === null) return null
      return { type: 'unary', op: t.value, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) return null
    if (t.type === 'number') {
      this.next()
      return { type: 'num', value: Number(t.value) }
    }
    if (t.type === 'lparen') {
      this.next()
      const inner = this.parseComparison()
      if (inner === null) return null
      const close = this.peek()
      if (!close || close.type !== 'rparen') return null
      this.next()
      return inner
    }
    if (t.type === 'word') {
      this.next()
      const next = this.peek()
      if (next && next.type === 'lparen') {
        this.next()
        const args = this.parseArgList()
        if (args === null) return null
        const close = this.peek()
        if (!close || close.type !== 'rparen') return null
        this.next()
        return { type: 'call', name: t.upper, args }
      }
      if (t.upper === 'TRUE') return { type: 'bool', value: true }
      if (t.upper === 'FALSE') return { type: 'bool', value: false }
      return { type: 'cell', word: t.upper }
    }
    return null
  }

  parseArgList() {
    const args = []
    if (this.peek() && this.peek().type === 'rparen') return args
    for (;;) {
      const arg = this.parseArg()
      if (arg === null) return null
      args.push(arg)
      const t = this.peek()
      if (t && t.type === 'comma') {
        this.next()
        continue
      }
      return args
    }
  }

  parseArg() {
    const a = this.peek()
    const b = this.peek(1)
    const c = this.peek(2)
    if (a && a.type === 'word' && b && b.type === 'colon' && c && c.type === 'word') {
      const after = this.peek(3)
      if (after && after.type !== 'comma' && after.type !== 'rparen') {
        // Not a bare range; fall through to normal expression parsing,
        // which will fail on the stray colon.
      } else {
        this.pos += 3
        return { type: 'range', from: a.upper, to: c.upper }
      }
    }
    return this.parseComparison()
  }
}

/** Parse a formula body (without the leading `=`) into an AST, or null. */
export function parseFormula(text) {
  const tokens = tokenize(text)
  if (tokens === null) return null
  const parser = new Parser(tokens)
  return parser.parseFormula()
}
"}

