{"file_path":"src/sheet.js","content":"/**
 * Parsing of the sheet text format into a map of declared cells.
 */

import { parseAddress, formatAddress, addressKey } from './address.js'

export class SheetError extends Error {}

/**
 * Split sheet text into lines, dropping the empty tail a trailing newline
 * leaves.
 */
function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Parse sheet text into an ordered array of { key, address, content }
 * records, one per declared cell, sorted by ascending column then row.
 * Throws SheetError on an invalid address or a duplicate declaration.
 */
export function parseSheet(input) {
  const cells = new Map()
  const lines = splitLines(input)
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    const stripped = line.replace(/^[ \t]*/, '')
    if (stripped === '' || stripped.startsWith('#')) continue
    const wsIndex = stripped.search(/[ \t]/)
    let addressText
    let content
    if (wsIndex === -1) {
      addressText = stripped
      content = ''
    } else {
      addressText = stripped.slice(0, wsIndex)
      const rest = stripped.slice(wsIndex)
      const run = /^[ \t]+/.exec(rest)
      content = rest.slice(run[0].length)
    }
    const addr = parseAddress(addressText)
    if (addr === null) {
      throw new SheetError(`line ${lineNo}: invalid cell address ${addressText.toUpperCase()}`)
    }
    const key = addressKey(addr)
    const canonical = formatAddress(addr)
    if (cells.has(key)) {
      throw new SheetError(`line ${lineNo}: cell ${canonical} is declared twice`)
    }
    cells.set(key, { key, address: canonical, content })
  }
  const ordered = [...cells.values()]
  ordered.sort((a, b) => a.key - b.key)
  return ordered
}
"}

