 * Renders a parsed document tree (see parser.js) as either canonical JSON
 * or the flat `keys` listing.
 */

function codePointCompare(a, b) {
  const A = Array.from(a)
  const B = Array.from(b)
  const len = Math.min(A.length, B.length)
  for (let i = 0; i < len; i++) {
    const ca = A[i].codePointAt(0)
    const cb = B[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return A.length - B.length
}

function sortedKeys(entries) {
  return [...entries.keys()].sort(codePointCompare)
}

function serialize(node, indent) {
  const pad = '  '.repeat(indent)
  const padInner = '  '.repeat(indent + 1)
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node.entries)
      if (keys.length === 0) return '{}'
      const lines = keys.map((k, idx) => {
        const v = node.entries.get(k)
        const comma = idx < keys.length - 1 ? ',' : ''
        return `${padInner}${JSON.stringify(k)}: ${serialize(v, indent + 1)}${comma}`
      })
      return `{\n${lines.join('\n')}\n${pad}}`
    }
    case 'array':
    case 'array-of-tables': {
      const items = node.items
      if (items.length === 0) return '[]'
      const lines = items.map((item, idx) => {
        const comma = idx < items.length - 1 ? ',' : ''
        return `${padInner}${serialize(item, indent + 1)}${comma}`
      })
      return `[\n${lines.join('\n')}\n${pad}]`
    }
    default:
      return JSON.stringify(node.value)
  }
}

export function toJson(root) {
  return serialize(root, 0)
}

function typeOf(node) {
  switch (node.kind) {
    case 'table': return 'table'
    case 'array':
    case 'array-of-tables': return 'array'
    default: return node.kind
  }
}

function walk(node, path, lines) {
  if (node.kind === 'table') {
    for (const k of sortedKeys(node.entries)) {
      const child = node.entries.get(k)
      const p = path === '' ? k : `${path}.${k}`
      lines.push(`${p} ${typeOf(child)}`)
      walk(child, p, lines)
    }
  } else if (node.kind === 'array' || node.kind === 'array-of-tables') {
    node.items.forEach((item, idx) => {
      const p = `${path}[${idx}]`
      lines.push(`${p} ${typeOf(item)}`)
      walk(item, p, lines)
    })
  }
}

export function toKeys(root) {
  const lines = []
  walk(root, '', lines)
  return lines.map((l) => `${l}\n`).join('')
}
