{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-MIcMdZ/src/regions.js","content":"/**
 * Groups the changes from both sides of a merge into regions and resolves
 * each one.
 */

import { computeChanges } from './diff.js'

/**
 * @typedef {Object} StableRegion
 * @property {'stable'} kind
 * @property {string[]} lines
 *
 * @typedef {Object} ResolvedRegion
 * @property {'mine' | 'theirs' | 'both'} kind
 * @property {string[]} lines
 *
 * @typedef {Object} ConflictRegion
 * @property {'conflict'} kind
 * @property {string[]} mine
 * @property {string[]} base
 * @property {string[]} theirs
 *
 * @typedef {StableRegion | ResolvedRegion | ConflictRegion} Region
 */

function linesEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

/**
 * Runs one side's own changes within a region through the moved-back,
 * moved-forward rule and returns that side's replacement lines for the
 * region.
 *
 * @param {import('./diff.js').Change[]} ownChanges changes for this side, in base order
 * @param {string[]} base the whole base document
 * @param {string[]} side the whole side document
 * @param {number} regionStart
 * @param {number} regionEnd
 * @returns {string[]}
 */
function sideLinesForRegion(ownChanges, base, side, regionStart, regionEnd) {
  if (ownChanges.length === 0) {
    return base.slice(regionStart, regionEnd)
  }
  const baseMinStart = ownChanges[0].baseStart
  const baseMaxEnd = ownChanges[ownChanges.length - 1].baseEnd
  const sideMinStart = ownChanges[0].sideStart
  const sideMaxEnd = ownChanges[ownChanges.length - 1].sideEnd
  return [
    ...base.slice(regionStart, baseMinStart),
    ...side.slice(sideMinStart, sideMaxEnd),
    ...base.slice(baseMaxEnd, regionEnd),
  ]
}

/**
 * Diffs `mine` and `theirs` against `base`, groups the resulting changes into
 * regions, and resolves each region.
 *
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 * @returns {Region[]}
 */
export function computeRegions(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine).map(change => ({ ...change, side: 'mine' }))
  const theirsChanges = computeChanges(base, theirs).map(change => ({ ...change, side: 'theirs' }))

  const changes = []
  let mi = 0
  let ti = 0
  while (mi < mineChanges.length && ti < theirsChanges.length) {
    if (mineChanges[mi].baseStart <= theirsChanges[ti].baseStart) {
      changes.push(mineChanges[mi++])
    } else {
      changes.push(theirsChanges[ti++])
    }
  }
  while (mi < mineChanges.length) changes.push(mineChanges[mi++])
  while (ti < theirsChanges.length) changes.push(theirsChanges[ti++])

  const regions = []
  let cursor = 0
  let idx = 0
  while (idx < changes.length) {
    const group = [changes[idx]]
    let start = changes[idx].baseStart
    let end = changes[idx].baseEnd
    idx++
    while (idx < changes.length && changes[idx].baseStart <= end) {
      end = Math.max(end, changes[idx].baseEnd)
      group.push(changes[idx])
      idx++
    }

    if (cursor < start) {
      regions.push({ kind: 'stable', lines: base.slice(cursor, start) })
    }

    const ownMine = group.filter(c => c.side === 'mine')
    const ownTheirs = group.filter(c => c.side === 'theirs')
    const mineLines = sideLinesForRegion(ownMine, base, mine, start, end)
    const theirsLines = sideLinesForRegion(ownTheirs, base, theirs, start, end)
    const baseLines = base.slice(start, end)

    if (linesEqual(mineLines, theirsLines)) {
      regions.push({ kind: ownMine.length > 0 && ownTheirs.length > 0 ? 'both' : 'mine', lines: mineLines })
    } else if (linesEqual(mineLines, baseLines)) {
      regions.push({ kind: 'theirs', lines: theirsLines })
    } else if (linesEqual(theirsLines, baseLines)) {
      regions.push({ kind: 'mine', lines: mineLines })
    } else {
      regions.push({ kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }

    cursor = end
  }

  if (cursor < base.length) {
    regions.push({ kind: 'stable', lines: base.slice(cursor, base.length) })
  }

  return regions
}
"}

