 * Parses the line-oriented election format described in the task: a single
 * `candidates` directive followed by any number of `ballot` directives.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(line, message) {
    super(line === null ? `error: ${message}` : `error: line ${line}: ${message}`)
    this.line = line
  }
}

/**
 * @param {string} input raw standard input
 * @returns {{ candidates: string[], ballots: { count: number, choices: string[] }[] }}
 */
