    super(message)
    this.name = 'EnvError'
    this.line = line
    this.column = column
  }
}

/** Every schema key's environment variable name, `CONF_` followed by the key upper-cased with `.` as `_`. */
const KEY_BY_NAME = new Map(SETTINGS.map(declared => [`CONF_${declared.key.toUpperCase().replaceAll('.', '_')}`, declared.key]))

/**
 * Parse the environment layer's text into its settings.
 * @param {string} text - standard input's whole text.
 * @returns {Map<string, {text: string, line: number, column: number}>} each schema key's raw value
 *   and the position of its first character (or, when empty, one past the line's last non-space
 *   character), in the order the input writes them.
 * @throws {EnvError} on the first line the grammar refuses.
 */
export function parseEnv(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const values = new Map()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const split = trimmed.indexOf('=')
    if (split === -1) throw new EnvError(line, indent(raw), 'expected NAME=VALUE')
    const name = trimmed.slice(0, split).trim()
    if (name === '') throw new EnvError(line, indent(raw), 'expected a variable name')
