/**
 * Merge named layers, later over earlier.
 * @param {readonly {name: string, values: Map<string, *>}[]} layers - the layers, weakest first.
 * @returns {Map<string, {value: *, layer: string}>} each key's winning value and the name of the
 *   layer that won it.
 */
export function merge(layers) {
  const merged = new Map()
  for (const layer of layers) {
    for (const [key, value] of layer.values) merged.set(key, { value, layer: layer.name })
  }
  return merged
}
