{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-PwoWs5/src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies. Precedence, loosest first:
 * comparisons, then `+`/`-`, then `*`/`/`, then `^` (right-associative),
 * then a leading sign (tighter than `^`).
 *
 * A range (`A1:B3`) is only accepted directly as a function-call argument.
 */

import { tokenize, LexError } from './lexer.js'

export class ParseError extends Error {}

const COMPARATORS = ['=', '<>', '<', '<=', '>', '>=']

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(k = 0) {
    return this.tokens[this.pos + k]
  }

  next() {
    return this.tokens[this.pos++]
  }

  isOp(value) {
    const t = this.peek()
    return t.type === 'OP' && t.value === value
  }

  parseExpr() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek().type === 'OP' && COMPARATORS.includes(this.peek().value)) {
      const op = this.next().value
      const right = this.parseAdditive()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.isOp('+') || this.isOp('-')) {
      const op = this.next().value
      const right = this.parseMultiplicative()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.isOp('*') || this.isOp('/')) {
      const op = this.next().value
      const right = this.parsePower()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parsePower() {
    const base = this.parseUnary()
    if (this.isOp('^')) {
      this.next()
      const right = this.parsePower()
      return { type: 'binop', op: '^', left: base, right }
    }
    return base
  }

  parseUnary() {
    if (this.isOp('-') || this.isOp('+')) {
      const op = this.next().value
      const operand = this.parsePrimary()
      return { type: 'unary', op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (t.type === 'NUMBER') {
      this.next()
      return { type: 'num', value: Number(t.value) }
    }
    if (t.type === 'LPAREN') {
      this.next()
      const expr = this.parseExpr()
      this.expect('RPAREN')
      return expr
    }
    if (t.type === 'IDENT') {
      this.next()
      const upper = t.value.toUpperCase()
      if (upper === 'TRUE') return { type: 'bool', value: true }
      if (upper === 'FALSE') return { type: 'bool', value: false }
      if (this.peek().type === 'LPAREN') {
        this.next()
        const args = this.parseArgs()
        this.expect('RPAREN')
        return { type: 'call', name: upper, args }
      }
      return { type: 'ref', word: upper }
    }
    throw new ParseError('unexpected token')
  }

  parseArgs() {
    const args = []
    if (this.peek().type === 'RPAREN') return args
    for (;;) {
      if (
        this.peek().type === 'IDENT' &&
        this.peek(1) &&
        this.peek(1).type === 'COLON' &&
        this.peek(2) &&
        this.peek(2).type === 'IDENT'
      ) {
        const from = this.next().value.toUpperCase()
        this.next()
        const to = this.next().value.toUpperCase()
        args.push({ type: 'range', from, to })
      } else {
        args.push(this.parseExpr())
      }
      if (this.peek().type === 'COMMA') {
        this.next()
        continue
      }
      break
    }
    return args
  }

  expect(type) {
    if (this.peek().type !== type) throw new ParseError(`expected ${type}`)
    this.next()
  }
}

/** Parses a formula body. Returns the AST, or null when the grammar rejects it. */
export function parseFormula(body) {
  try {
    const tokens = tokenize(body)
    const parser = new Parser(tokens)
    const ast = parser.parseExpr()
    if (parser.peek().type !== 'EOF') return null
    return ast
  } catch (e) {
    if (e instanceof ParseError || e instanceof LexError) return null
    throw e
  }
}
"}

