 * Parses the sheet source text into declared cells, in the order given by
 * the specification: split on newlines (dropping the trailing empty line a
 * final newline leaves), strip leading spaces/tabs per line, skip blank or
 * `#`-comment lines, then split each remaining line into an address token
 * and verbatim content.
 */

import { parseAddressWord } from './address.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
  }
}

function splitLine(stripped) {
  let i = 0
  while (i < stripped.length && stripped[i] !== ' ' && stripped[i] !== '\t') i++
  const addr = stripped.slice(0, i)
  let j = i
  while (j < stripped.length && (stripped[j] === ' ' || stripped[j] === '\t')) j++
  const content = stripped.slice(j)
  return { addr, content }
}

/**
 * Parses sheet source text. Returns { order, contents } where `order` is
 * the list of canonical address keys in declaration order and `contents`
 * maps each key to its cell content. Throws SheetError on the first
 * invalid address or duplicate declaration, with a `line` property set.
 */
export function parseSheet(source) {
  const lines = source.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const order = []
  const contents = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    let s = lines[i]
    let k = 0
    while (k < s.length && (s[k] === ' ' || s[k] === '\t')) k++
    s = s.slice(k)
    if (s === '' || s.startsWith('#')) continue

    const { addr, content } = splitLine(s)
    const info = parseAddressWord(addr)
    if (!info) {
      const e = new SheetError(`invalid cell address ${addr}`)
      e.line = lineNo
      throw e
    }
    if (contents.has(info.key)) {
      const e = new SheetError(`cell ${info.key} is declared twice`)
      e.line = lineNo
      throw e
    }
    contents.set(info.key, content)
    order.push(info.key)
  }

  return { order, contents }
}
"}

