 * Tokenizer for formula bodies (the text after the leading `=`).
 */

class LexError extends Error {}

const TWO_CHAR_OPS = ['<=', '>=', '<>']
const ONE_CHAR_OPS = ['^', '*', '/', '+', '-', '=', '<', '>']

function tokenize(body) {
  const tokens = []
  let i = 0
  const n = body.length
  while (i < n) {
    const ch = body[i]
    if (ch === ' ' || ch === '\t') {
      i++
