{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-TW57ce/src/sheet.js","content":"/**
 * Parsing the sheet fed on standard input into a map of declared cells.
 */

import { parseAddress } from './address.js'

class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

/**
 * Parse the sheet text into a Map from canonical address to its raw content.
 * Throws SheetError on an invalid address or a cell declared twice.
 */
function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const stripped = lines[i].replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    const addrMatch = /^(\S+)/.exec(stripped)
    const addrToken = addrMatch[1]
    const rest = stripped.slice(addrToken.length)
    const wsMatch = /^[ \t]*/.exec(rest)
    const content = rest.slice(wsMatch[0].length)

    const addr = parseAddress(addrToken)
    if (!addr) throw new SheetError(lineNo, `invalid cell address ${addrToken.toUpperCase()}`)
    if (cells.has(addr.text)) throw new SheetError(lineNo, `cell ${addr.text} is declared twice`)
    cells.set(addr.text, { content })
  }
  return cells
}

export { parseSheet, SheetError }
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-TW57ce/src/deps.js","content":"/**
 * Static dependency extraction: the cells a formula's AST names directly,
 * with ranges expanded, regardless of what the formula evaluates to.
 */

import { parseAddress, rectangleAddresses, sortAddresses } from './address.js'

function collectDeps(ast) {
  const names = new Set()

  function addAddress(text) {
    const a = parseAddress(text)
    if (a) names.add(a.text)
  }

  function walk(node) {
    switch (node.type) {
      case 'Number':
      case 'Bool':
        return
      case 'Address':
        addAddress(node.text)
        return
      case 'Range': {
        const from = parseAddress(node.from)
        const to = parseAddress(node.to)
        if (from && to) for (const a of rectangleAddresses(from, to)) names.add(a)
        return
      }
      case 'Unary':
        walk(node.node)
        return
      case 'Binary':
        walk(node.left)
        walk(node.right)
        return
      case 'Call':
        for (const arg of node.args) walk(arg)
        return
      default:
        return
    }
  }

  walk(ast)
  return sortAddresses([...names])
}

export { collectDeps }
"}

