  '=': (c) => c === 0,
  '<>': (c) => c !== 0,
  '<': (c) => c < 0,
  '<=': (c) => c <= 0,
  '>': (c) => c > 0,
  '>=': (c) => c >= 0,
}

const MULTI_ARG_FNS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.parsedCache = new Map()
    this.valueCache = new Map()
    this.visiting = new Set()
  }

  parseCellContent(addr) {
    if (this.parsedCache.has(addr)) return this.parsedCache.get(addr)
    const decl = this.cells.get(addr)
    const content = decl ? decl.content : ''
    let result
    if (content.startsWith('=')) {
      const parsed = parseFormula(content.slice(1))
      result = parsed.ok ? { kind: 'formula', ast: parsed.ast } : { kind: 'formula-error' }
    } else {
      result = { kind: 'literal', value: parseLiteral(content) }
    }
    this.parsedCache.set(addr, result)
    return result
  }

  getCellValue(addr) {
    if (this.valueCache.has(addr)) return this.valueCache.get(addr)
    if (this.visiting.has(addr)) return err('#CYCLE!')
    this.visiting.add(addr)
    const parsed = this.parseCellContent(addr)
    let result
    if (parsed.kind === 'literal') result = parsed.value
    else if (parsed.kind === 'formula-error') result = err('#ERR!')
    else result = this.evalNode(parsed.ast)
    this.visiting.delete(addr)
    this.valueCache.set(addr, result)
    return result
  }

  /** Evaluate an argument node into its list of contributed values (a range expands to many). */
  expandArg(node) {
    if (node.type === 'Range') {
      const from = parseAddress(node.from)
      const to = parseAddress(node.to)
      if (!from || !to) return [err('#REF!')]
      return rectangleAddresses(from, to).map((a) => this.getCellValue(a))
    }
    return [this.evalNode(node)]
  }

  evalNode(node) {
    switch (node.type) {
      case 'Number':
        return num(node.value)
      case 'Bool':
        return bool(node.value)
      case 'Address': {
        const a = parseAddress(node.text)
        if (!a) return err('#REF!')
        return this.getCellValue(a.text)
      }
      case 'Unary':
        return this.evalUnary(node)
      case 'Binary':
        return this.evalBinary(node)
      case 'Call':
        return this.evalCall(node)
      default:
        return err('#ERR!')
    }
  }

  evalUnary(node) {
    const v = this.evalNode(node.node)
    if (v.type === 'error') return v
    const n = toNumber(v)
    if (n.type === 'error') return n
    return finiteNum(node.op === '-' ? -n.value : n.value)
  }

