      const vErr = firstError(vals)
      if (vErr) return vErr
      if (vals.length !== 1) return err('#VALUE!')
      const n = toNumber(vals[0])
      if (n.type === 'error') return n
      return finiteNum(Math.abs(n.value))
    }

    if (MULTI_ARG_FNS.has(name)) {
      if (args.length < 1) return err('#ERR!')
      const allVals = []
      for (const a of args) allVals.push(...this.expandArg(a))
      const anyErr = firstError(allVals)
      if (anyErr) return anyErr

