 * @returns {{ok: true, out: string} | {ok: false, message: string}} the rendered text, or the
 *   failure the specification words, without its position.
 */
export function coerce(declared, text) {
  switch (declared.type) {
    case 'string':
      return { ok: true, out: text }
    case 'integer':
      if (!INTEGER.test(text)) return { ok: false, message: `${declared.key} is not an integer: ${text}` }
      return { ok: true, out: text }
    case 'boolean':
      if (text !== 'true' && text !== 'false') return { ok: false, message: `${declared.key} is not a boolean: ${text}` }
      return { ok: true, out: text }
    case 'enum':
      if (!declared.members.includes(text)) {
        return { ok: false, message: `${declared.key} is not one of ${declared.members.join('|')}: ${text}` }
      }
      return { ok: true, out: text }
    case 'duration': {
      const match = DURATION.exec(text)
      if (!match) return { ok: false, message: `${declared.key} is not a duration: ${text}` }
      return { ok: true, out: String(Number(match[1]) * DURATION_MS[match[2]]) }
    }
    case 'list': {
      if (text === '') return { ok: true, out: '' }
      const items = text.split(',').map(item => item.trim())
      if (items.some(item => item === '')) return { ok: false, message: `${declared.key} has an empty item: ${text}` }
      const seen = new Set()
      const kept = []
      for (const item of items) {
        if (seen.has(item)) continue
        seen.add(item)
        kept.push(item)
      }
      return { ok: true, out: kept.join(',') }
    }
    default:
      throw new Error(`unknown type ${declared.type}`)
  }
