 * RFC 3986 generic-syntax parsing, normalization and reference resolution.
 *
 * All functions here work on plain objects of the shape
 * `{ scheme, authority, path, query, fragment }`, where every field is
 * either a string or `null` for "absent". `path` is always a string
 * (RFC 3986 never lets it be absent).
 */

const DEFAULT_PORTS = { http: '80', https: '443', ws: '80', wss: '443', ftp: '21' }

/** Thrown when a component holds a `%` not followed by two hex digits. */
export class TruncatedPercentEncodingError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

/**
 * Splits a URI reference into scheme, authority, path, query and fragment
 * following RFC 3986's generic syntax. Never throws: syntactic looseness is
 * absorbed here, and only percent-encoding is later treated as an error.
 */
export function parseReference(input) {
  let rest = input
  let scheme = null

  let colonIndex = -1
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === ':') {
      colonIndex = i
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }
  if (colonIndex !== -1) {
    scheme = rest.slice(0, colonIndex)
    rest = rest.slice(colonIndex + 1)
  }

  let authority = null
  if (rest.startsWith('//')) {
    const afterSlashes = rest.slice(2)
    let end = afterSlashes.length
    for (let i = 0; i < afterSlashes.length; i++) {
      if (afterSlashes[i] === '/' || afterSlashes[i] === '?' || afterSlashes[i] === '#') {
        end = i
        break
      }
    }
    authority = afterSlashes.slice(0, end)
    rest = afterSlashes.slice(end)
  }

  const hashIndex = rest.indexOf('#')
  let beforeFragment
  let fragment
  if (hashIndex === -1) {
    beforeFragment = rest
    fragment = null
  } else {
    beforeFragment = rest.slice(0, hashIndex)
    fragment = rest.slice(hashIndex + 1)
  }

  const questionIndex = beforeFragment.indexOf('?')
  let path
  let query
  if (questionIndex === -1) {
    path = beforeFragment
    query = null
  } else {
    path = beforeFragment.slice(0, questionIndex)
    query = beforeFragment.slice(questionIndex + 1)
  }

  return { scheme, authority, path, query, fragment }
}

/**
 * Splits an authority into userinfo, host and port: userinfo is everything
 * before the last `@`, port is everything after the first `:` following the
 * last `]`, and host is what remains between them.
 */
function splitAuthority(authority) {
  if (authority === null) return { userinfo: null, host: null, port: null }

  const lastAt = authority.lastIndexOf('@')
  let userinfo = null
  let hostAndPort = authority
  if (lastAt !== -1) {
    userinfo = authority.slice(0, lastAt)
    hostAndPort = authority.slice(lastAt + 1)
  }

  const lastBracket = hostAndPort.lastIndexOf(']')
  const searchFrom = lastBracket === -1 ? 0 : lastBracket + 1
