/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { parseReference, normalize, resolveTarget, TruncatedPercentEncodingError } from './uri.js'

class RecordError extends Error {}

/** Splits stdin into records: newline-separated lines, minus the empty tail a trailing newline leaves. */
function splitRecords(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function processRecord(mode, record) {
  if (mode === 'normalize') {
    return normalize(parseReference(record))
  }

  const spaceIndex = record.indexOf(' ')
  if (spaceIndex === -1) throw new RecordError('expected a base and a reference')

  const base = parseReference(record.slice(0, spaceIndex))
  if (base.scheme === null) throw new RecordError('the base has no scheme')

  const ref = parseReference(record.slice(spaceIndex + 1))
  return normalize(resolveTarget(base, ref))
}

function main() {
  const args = process.argv.slice(2)
  const mode = args.length === 1 ? args[0] : null
  if (mode !== 'normalize' && mode !== 'resolve') {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const input = readFileSync(0, 'utf8')
  const records = splitRecords(input)
  const results = []

  for (let i = 0; i < records.length; i++) {
    const lineNumber = i + 1
    try {
      results.push(processRecord(mode, records[i]))
    } catch (error) {
      const message = error instanceof RecordError || error instanceof TruncatedPercentEncodingError ? error.message : null
      if (message === null) throw error
      process.stderr.write(`error: line ${lineNumber}: ${message}\n`)
      process.exit(2)
    }
  }

  process.stdout.write(results.map((line) => line + '\n').join(''))
}

main()
"}

