}

/** Whether a word is a usable path: the allowed characters, no leading slash, no `..` segment. */
function isPath(word) {
  if (!PATH_CHARS.test(word)) return false
  if (word.startsWith('/')) return false
  return !word.split('/').includes('..')
}

/**
 * Every input line, with the empty tail a trailing newline leaves dropped.
 * @param {string} text - the whole input.
 * @returns {string[]} the lines.
 */
export function splitLines(text) {
  const split = text.split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

/**
 * Parse a task file into its tasks.
 * @param {string[]} lines - the input lines.
 * @returns {Map<string, {name: string, command: string, needs: string[], reads: string[], writes: string[]}>}
 *   the tasks by name, in declaration order.
 */
export function parse(lines) {
  const tasks = new Map()
  const referenced = []
  const needsAttachments = []
  const fileAttachments = []
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const text = raw.trim()
    if (text === '' || text.startsWith('#')) continue
    const words = text.split(/\s+/u)
    if (words[0] === 'task') {
      if (words.length < 3) throw new ParseError(line, 'expected task <name> <word>...')
      const name = words[1]
      if (!isName(name)) throw new ParseError(line, `invalid task name ${name}`)
      if (tasks.has(name)) throw new ParseError(line, `task ${name} is declared twice`)
      tasks.set(name, { name, command: words.slice(2).join(' '), needs: [], reads: [], writes: [] })
    } else if (words[0] === 'needs') {
      if (words.length < 3) throw new ParseError(line, 'expected needs <name> <dependency>...')
      const [, name, ...values] = words
      if (!isName(name)) throw new ParseError(line, `invalid task name ${name}`)
      referenced.push(name)
      for (const value of values) {
        if (!isName(value)) throw new ParseError(line, `invalid task name ${value}`)
        referenced.push(value)
      }
      needsAttachments.push({ name, values })
    } else if (words[0] === 'reads' || words[0] === 'writes') {
      const kind = words[0]
      if (words.length < 3) throw new ParseError(line, `expected ${kind} <name> <path>...`)
      const [, name, ...paths] = words
      for (const path of paths) {
        if (!isPath(path)) throw new ParseError(line, `invalid path ${path}`)
      }
      referenced.push(name)
      fileAttachments.push({ kind, name, paths })
    } else {
      throw new ParseError(line, `unknown directive ${words[0]}`)
    }
  }
  for (const name of referenced) {
    if (!tasks.has(name)) throw new ParseError(0, `unknown task ${name}`)
  }
  for (const { name, values } of needsAttachments) {
    const list = tasks.get(name).needs
    for (const value of values) {
      if (!list.includes(value)) list.push(value)
    }
  }
  for (const { kind, name, paths } of fileAttachments) {
    const list = tasks.get(name)[kind]
    for (const path of paths) {
      if (!list.includes(path)) list.push(path)
    }
  }
  return tasks
}

/**
 * Parse a digest snapshot into the digest recorded for each path.
 * @param {string[]} lines - the snapshot's own lines.
 * @returns {Map<string, string>} the recorded digest by path.
 */
export function parseSnapshot(lines) {
  const digests = new Map()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const text = raw.trim()
    if (text === '' || text.startsWith('#')) continue
    const words = text.split(/\s+/u)
    if (words.length !== 2) throw new SnapshotError(line, 'expected <path> <digest>')
    const [path, digest] = words
    if (!DIGEST.test(digest)) throw new SnapshotError(line, `invalid digest ${digest}`)
    if (digests.has(path)) throw new SnapshotError(line, `path ${path} is recorded twice`)
    digests.set(path, digest)
  }
  return digests
}
"}

