    if (!tasks.has(name)) throw new ParseError(0, `unknown task ${name}`)
  }
  for (const { name, values } of needsAttachments) {
    const list = tasks.get(name).needs
    for (const value of values) {
      if (!list.includes(value)) list.push(value)
    }
  }
  for (const { kind, name, paths } of fileAttachments) {
    const list = tasks.get(name)[kind]
    for (const path of paths) {
      if (!list.includes(path)) list.push(path)
    }
  }
