/** A dependency cycle a depth-first search found, carrying the names from the re-entered task back to itself. */
export class CycleError extends Error {
  /**
   * @param {string[]} names - the re-entered task, through the search stack, back to a repeat of itself.
   */
  constructor(names) {
    super(`cycle: ${names.join(' -> ')}`)
    this.name = 'CycleError'
    this.names = names
  }
}

/**
 * The first cycle a depth-first search finds, starting from each task in ascending name order and
 * walking each task's dependencies in ascending name order.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]|null} the cycle's names, from the re-entered task back to a repeat of itself, or null.
 */
function findCycle(tasks) {
  const state = new Map()
  const stack = []

  function visit(name) {
    state.set(name, 'gray')
    stack.push(name)
    for (const dep of [...tasks.get(name).needs].sort()) {
      const depState = state.get(dep)
      if (depState === 'gray') {
        const start = stack.indexOf(dep)
        return [...stack.slice(start), dep]
      }
      if (depState === undefined) {
        const found = visit(dep)
        if (found) return found
      }
    }
    stack.pop()
    state.set(name, 'black')
    return null
  }

  for (const name of [...tasks.keys()].sort()) {
    if (!state.has(name)) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}

/**
 * The tasks in run order: repeatedly the lexicographically smallest task whose dependencies have
 * all been emitted. Refuses a cyclic graph instead of leaving the tasks in the cycle out.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]} the names in run order.
 * @throws {CycleError} when the graph has a dependency cycle.
 */
export function order(tasks) {
  const cycle = findCycle(tasks)
  if (cycle) throw new CycleError(cycle)

  const remaining = new Set(tasks.keys())
  const emitted = new Set()
  const out = []
  while (remaining.size > 0) {
    const ready = [...remaining].filter(name => tasks.get(name).needs.every(need => emitted.has(need))).sort()
    remaining.delete(ready[0])
    emitted.add(ready[0])
    out.push(ready[0])
  }
  return out
}
"}

