 * only to phrase the error messages of anything nested inside it. */
export function parseValue(ctx, basePath) {
  const c = peekSignificant(ctx)
  if (c === undefined || c === ',' || c === ']' || c === '}') fail(ctx, 'expected a value')
  if (c === '"') return parseBasicString(ctx)
  if (c === "'") return parseLiteralString(ctx)
  if (c === '[') return parseArray(ctx, basePath)
  if (c === '{') return parseInlineTable(ctx, basePath)
  return parseBareword(ctx)
}

