  ctx.pos++ // '['
  const arr = newArray()
  if (peekSignificant(ctx) === ']') {
    ctx.pos++
    return arr
  }
  while (true) {
    arr.items.push(parseValue(ctx, basePath))
    const c = peekSignificant(ctx)
    if (c === ']') {
      ctx.pos++
      return arr
    }
    if (c === ',') {
      ctx.pos++
      if (peekSignificant(ctx) === ']') {
        ctx.pos++
        return arr
      }
      continue
    }
    if (c === undefined) fail(ctx, 'unterminated array')
    fail(ctx, 'trailing text after a value')
  }
}

