  ctx.pos++ // '{'
  const table = newTable()
  if (peekSignificant(ctx) === '}') {
    ctx.pos++
    return table
  }
  while (true) {
    const segments = parseDottedName(ctx)
    if (peekSignificant(ctx) !== '=') fail(ctx, 'expected = in an inline table')
    ctx.pos++
    const value = parseValue(ctx, basePath.concat(segments))
    assignPath(table, segments, value, basePath, ctx.lineNo)
    const c = peekSignificant(ctx)
    if (c === '}') {
      ctx.pos++
      return table
    }
    if (c === ',') {
      ctx.pos++
      continue
    }
    if (c === undefined) fail(ctx, 'unterminated inline table')
    fail(ctx, 'trailing text after a value')
  }
}
