import { compareCodePoint } from './nodes.js'

function sortedKeys(node) {
  return [...node.map.keys()].sort(compareCodePoint)
}

function stringifyNode(node, depth) {
  const pad = '  '.repeat(depth)
  const pad1 = '  '.repeat(depth + 1)
  switch (node.t) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const parts = keys.map(
        (k) => `${pad1}${JSON.stringify(k)}: ${stringifyNode(node.map.get(k), depth + 1)}`,
      )
      return `{\n${parts.join(',\n')}\n${pad}}`
    }
    case 'arrayOfTables':
    case 'array': {
      if (node.items.length === 0) return '[]'
      const parts = node.items.map((it) => pad1 + stringifyNode(it, depth + 1))
      return `[\n${parts.join(',\n')}\n${pad}]`
    }
    case 'string':
      return JSON.stringify(node.v)
    case 'boolean':
      return node.v ? 'true' : 'false'
    case 'integer':
      return node.v.toString()
    case 'float':
      return JSON.stringify(node.v)
    default:
      throw new Error(`unreachable node type ${node.t}`)
  }
}

/** Renders the document as JSON, indented by two spaces, plus a trailing newline. */
export function toJSON(root) {
  return `${stringifyNode(root, 0)}\n`
