{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-buzBUs/src/engine.js","content":"/**
 * Replays a parsed program's events against its policies, yielding one
 * verdict per event in log order.
 */

import { buildPolicy } from './policies.js'

/** Finds the longest routed prefix the key starts with, or null. */
function matchRoute(routes, key) {
  let best = null
  for (const prefix of routes.keys()) {
    if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) {
      best = prefix
    }
  }
  return best
}

/**
 * Runs every event through its route's policies, returning
 * `{ tick, key, allow, denyPolicy }` for each in order. `denyPolicy` is set
 * only when `allow` is false.
 */
export function replay(program) {
  const { policies: declared, routes, events } = program
  const live = new Map()
  for (const [name, decl] of declared) live.set(name, buildPolicy(decl))

  const results = []
  for (const { tick, key } of events) {
    const prefix = matchRoute(routes, key)
    if (prefix === null) {
      results.push({ tick, key, allow: true })
      continue
    }
    const names = routes.get(prefix)
    const instances = names.map((name) => live.get(name))
    for (const instance of instances) instance.advance(key, tick)

    let denyIndex = -1
    for (let i = 0; i < instances.length; i++) {
      if (!instances[i].allow(key)) {
        denyIndex = i
        break
      }
    }

    if (denyIndex === -1) {
      for (const instance of instances) instance.commit(key, tick)
      results.push({ tick, key, allow: true })
    } else {
      results.push({ tick, key, allow: false, denyPolicy: names[denyIndex] })
    }
  }
  return results
}
"}

