 * Longest-common-subsequence diff between a base document and one side,
 * comparing whole lines as exact strings.
 */

/**
 * Finds the changes needed to turn `base` into `side`, using the LCS
 * tie-breaking rule from the specification: among equally long
 * subsequences, prefer the one whose matches occur earliest, breaking ties
 * between the two documents by advancing the base.
 *
 * Returns changes ordered by base position, each describing a run of base
 * lines (by index) replaced by a run of side lines (by index). An insertion
 * has an empty base run; a deletion has an empty side run.
 */
export function computeChanges(base, side) {
  const n = base.length
  const m = side.length

  // dp[i][j] = length of the LCS of base[i:] and side[j:].
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i][j] = base[i] === side[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }

  const changes = []
  let prevI = 0
  let prevJ = 0
  for (const [mi, mj] of matches) {
    if (mi > prevI || mj > prevJ) {
      changes.push({ baseStart: prevI, baseEnd: mi, sideStart: prevJ, sideEnd: mj })
    }
    prevI = mi + 1
    prevJ = mj + 1
  }
  if (prevI < n || prevJ < m) {
    changes.push({ baseStart: prevI, baseEnd: n, sideStart: prevJ, sideEnd: m })
  }
  return changes
}
"}

