  const mineChanges = computeChanges(base, mine).map(change => ({ ...change, side: 'mine' }))
  const theirsChanges = computeChanges(base, theirs).map(change => ({ ...change, side: 'theirs' }))

  const allChanges = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const groups = []
  for (const change of allChanges) {
    const last = groups[groups.length - 1]
    if (last && change.baseStart <= last.end) {
      last.end = Math.max(last.end, change.baseEnd)
      last.changes.push(change)
    } else {
      groups.push({ start: change.baseStart, end: change.baseEnd, changes: [change] })
    }
  }

  const regions = []
  let pos = 0
  for (const group of groups) {
    if (group.start > pos) {
      regions.push(makeStableRegion(base, pos, group.start))
    }
    regions.push(makeChangeRegion(base, mine, theirs, group))
    pos = group.end
  }
  if (base.length > pos) {
    regions.push(makeStableRegion(base, pos, base.length))
  }
  return regions
}

function makeStableRegion(base, start, end) {
  return { kind: 'stable', lines: base.slice(start, end) }
}

/**
 * Reconstructs one side's view of a region: base lines outside that side's
 * own changes, and that side's lines within them.
 */
function sideLines(base, side, changes, start, end) {
  const own = changes.filter(change => change.side === side).sort((a, b) => a.baseStart - b.baseStart)
  const result = []
  let pos = start
  const sideDoc = side === 'mine' ? changes.mine : changes.theirs
  for (const change of own) {
    result.push(...base.slice(pos, change.baseStart))
    result.push(...sideDoc.slice(change.sideStart, change.sideEnd))
    pos = change.baseEnd
  }
  result.push(...base.slice(pos, end))
  return result
}

