  const { start, end, changes } = group
  const hasMine = changes.some(change => change.side === 'mine')
  const hasTheirs = changes.some(change => change.side === 'theirs')
  const docs = { mine, theirs }
  const mineLines = sideLines(base, 'mine', changes.concat([{ mine, theirs }]).slice(0, changes.length).concat().map(c => c), start, end)
  return buildChangeRegion(base, mine, theirs, start, end, changes, hasMine, hasTheirs)
