  const baseLines = base.slice(start, end)
  const mineOwn = changes.filter(change => change.side === 'mine').sort((a, b) => a.baseStart - b.baseStart)
  const theirsOwn = changes.filter(change => change.side === 'theirs').sort((a, b) => a.baseStart - b.baseStart)
