{"file_path":"src/parse.js","content":"import { ElectionError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/**
 * Parses election text into `{ candidates, ballots }`, where `candidates` is
 * the array of names in declaration order and `ballots` is an array of
 * `{ count, ranking }` objects. Throws `ElectionError` on the first problem,
 * per the rules in the task specification.
 */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidates !== null || ballots.length > 0) {
        throw new ElectionError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 2) {
        throw new ElectionError('expected candidates <name>...', lineNumber)
      }
      candidates = []
      for (const name of tokens.slice(1)) {
        if (!NAME_RE.test(name)) {
          throw new ElectionError(`invalid candidate name ${name}`, lineNumber)
        }
        if (candidateSet.has(name)) {
          throw new ElectionError(`candidate ${name} is declared twice`, lineNumber)
        }
        candidateSet.add(name)
        candidates.push(name)
      }
    } else if (directive === 'ballot') {
      if (candidates === null) {
        throw new ElectionError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 3) {
        throw new ElectionError('expected ballot <count> <candidate>...', lineNumber)
      }
      const countText = tokens[1]
      if (!COUNT_RE.test(countText)) {
        throw new ElectionError('count must be a positive integer', lineNumber)
      }
      const count = Number(countText)
      const ranking = []
      const seen = new Set()
      for (const name of tokens.slice(2)) {
        if (!candidateSet.has(name)) {
          throw new ElectionError(`unknown candidate ${name}`, lineNumber)
        }
        if (seen.has(name)) {
          throw new ElectionError(`candidate ${name} is repeated`, lineNumber)
        }
        seen.add(name)
        ranking.push(name)
      }
      ballots.push({ count, ranking })
    } else {
      throw new ElectionError(`unknown directive ${directive}`, lineNumber)
    }
  }

  if (candidates === null) {
    throw new ElectionError('no candidates')
  }

  return { candidates, ballots }
}
"}

