/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import fs from 'node:fs'
import { normalize, parseUriReference, resolveReference, serialize } from './uri.js'

function readStdin() {
  return fs.readFileSync(0, 'utf8')
}

function splitLines(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function normalizeLine(line) {
  return serialize(normalize(parseUriReference(line)))
}

function resolveLine(line) {
  const spaceIndex = line.indexOf(' ')
  if (spaceIndex === -1) throw new Error('expected a base and a reference')

  const base = parseUriReference(line.slice(0, spaceIndex))
  if (base.scheme === null) throw new Error('the base has no scheme')

  const reference = parseUriReference(line.slice(spaceIndex + 1))
  return serialize(normalize(resolveReference(base, reference)))
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'normalize' && argv[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const mode = argv[0]
  const processLine = mode === 'normalize' ? normalizeLine : resolveLine
  const lines = splitLines(readStdin())

  const results = []
  for (let i = 0; i < lines.length; i++) {
    try {
      results.push(processLine(lines[i]))
    } catch (err) {
      process.stderr.write(`error: line ${i + 1}: ${err.message}\n`)
      process.exit(2)
    }
  }

  process.stdout.write(results.map((line) => line + '\n').join(''))
  process.exit(0)
}

main()
"}

