  for (const change of theirsChanges) combined.push({ ...change, side: 'theirs' })
  combined.sort((a, b) => a.baseStart - b.baseStart || (a.side === 'mine' ? -1 : 1) - (b.side === 'mine' ? -1 : 1))

  const regions = []
  let current = null
  for (const change of combined) {
    if (!current) {
      current = { baseStart: change.baseStart, baseEnd: change.baseEnd, changes: [change] }
    } else if (change.baseStart <= current.baseEnd) {
      current.baseEnd = Math.max(current.baseEnd, change.baseEnd)
      current.changes.push(change)
    } else {
