{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-qBaVhZ/src/render.js","content":"/**
 * Renders merge segments (see mergeDocuments) into the output lines for one
 * of the three CLI modes, and reports whether a conflict was written.
 *
 * @param {ReturnType<typeof import('./merge.js').mergeDocuments>} segments
 * @param {'merge'|'merge2'|'regions'} mode
 * @returns {{lines: string[], hasConflict: boolean}}
 */
export function render(segments, mode) {
  const lines = []
  let hasConflict = false
  for (const segment of segments) {
    if (segment.kind === 'conflict') {
      hasConflict = true
      if (mode === 'regions') {
        lines.push(`conflict mine=${segment.mineLines.length} base=${segment.baseLines.length} theirs=${segment.theirsLines.length}`)
        continue
      }
      lines.push('<<<<<<< mine')
      lines.push(...segment.mineLines)
      if (mode === 'merge') {
        lines.push('||||||| base')
        lines.push(...segment.baseLines)
      }
      lines.push('=======')
      lines.push(...segment.theirsLines)
      lines.push('>>>>>>> theirs')
      continue
    }
    if (mode === 'regions') {
      lines.push(`${segment.kind} ${segment.lines.length}`)
    } else {
      lines.push(...segment.lines)
    }
  }
  return { lines, hasConflict }
}
"}

