 * Tracks a cursor over the source text as an array of Unicode code points,
 * and the line/column position that reading each code point moves to.
 */

export class LexError extends Error {
  constructor(pos, message) {
    super(message)
    this.line = pos.line
    this.col = pos.col
  }
}

export class Scanner {
  constructor(input) {
    this.cps = Array.from(input)
    this.i = 0
    this.line = 1
    this.col = 1
  }

  eof() {
    return this.i >= this.cps.length
  }

  peek(offset = 0) {
    return this.cps[this.i + offset]
  }

  pos() {
    return { line: this.line, col: this.col }
  }

  advance() {
    const c = this.cps[this.i++]
    if (c === '\n') {
      this.line++
      this.col = 1
    } else if (c === '\t') {
      this.col = (Math.floor((this.col - 1) / 4) + 1) * 4 + 1
    } else {
      this.col++
    }
    return c
  }
}
"}

