{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-s7xveJ/src/parse.js","content":"/**
 * Parses the build-graph text format read from standard input into a
 * `{ tasks, deps }` graph, or throws a `CliError` describing the first
 * malformed line (or unknown reference) encountered.
 */

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

export class CliError extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
  }
}

export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const deps = new Map()
  const usages = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNo}: expected task <name> <cost>`, 2)
      }
      const [, name, costText] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNo}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(costText)) {
        throw new CliError(`line ${lineNo}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNo}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, Number(costText))
      if (!deps.has(name)) deps.set(name, new Set())
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNo}: expected dep <name> <dependency>...`, 2)
      }
      const [, name, ...rest] = words
      for (const n of [name, ...rest]) {
        if (!NAME_RE.test(n)) {
          throw new CliError(`line ${lineNo}: invalid task name ${n}`, 2)
        }
      }
      if (!deps.has(name)) deps.set(name, new Set())
      const set = deps.get(name)
      for (const dep of rest) set.add(dep)
      usages.push(name, ...rest)
    } else {
      throw new CliError(`line ${lineNo}: unknown directive ${directive}`, 2)
    }
  }

  for (const name of usages) {
    if (!tasks.has(name)) {
      throw new CliError(`unknown task ${name}`, 2)
    }
  }

  return { tasks, deps }
}
"}

