export function computePriorities(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, depSet] of deps) {
    for (const dep of depSet) dependents.get(dep).push(name)
  }

  const remaining = new Map()
  for (const name of tasks.keys()) remaining.set(name, dependents.get(name).length)

  const priority = new Map()
  const queue = [...tasks.keys()].filter((name) => remaining.get(name) === 0)

  for (let i = 0; i < queue.length; i++) {
    const name = queue[i]
    let downstream = 0
    for (const dependent of dependents.get(name)) {
      downstream = Math.max(downstream, priority.get(dependent))
    }
    priority.set(name, tasks.get(name) + downstream)

    for (const dep of deps.get(name) || []) {
      const left = remaining.get(dep) - 1
      remaining.set(dep, left)
      if (left === 0) queue.push(dep)
    }
  }

