/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { CliError, parseGraph } from './parse.js'
import { findCycle } from './cycle.js'
import { computeTiming } from './timing.js'
import { computePriorities } from './priority.js'
import { packSchedule } from './pack.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9][0-9]*$/

function fail(message, code) {
  process.stderr.write(`${message}\n`)
  process.exit(code)
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      fail('error: workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  fail(USAGE, 2)
  return undefined
}

function main() {
  const { mode, workers } = parseArgs(process.argv.slice(2))

  const input = readFileSync(0, 'utf8')

  let graph
  try {
    graph = parseGraph(input)
  } catch (err) {
    if (err instanceof CliError) fail(`error: ${err.message}`, err.code)
    throw err
  }
  const { tasks, deps } = graph

  const cycle = findCycle(tasks, deps)
  if (cycle) fail(`error: cycle: ${cycle.join(' -> ')}`, 3)

  const names = [...tasks.keys()].sort()

  if (mode === 'pack') {
    const priority = computePriorities(tasks, deps)
    const { workerLog, makespan } = packSchedule(tasks, deps, priority, workers)
    const lines = workerLog.map((entries, i) => {
      const suffix = entries.map((t) => ` ${t.name}@${t.start}-${t.finish}`).join('')
      return `worker ${i}:${suffix}`
    })
    lines.push(`makespan ${makespan}`)
    process.stdout.write(lines.join('\n') + '\n')
    return
  }

  const { start, finish, depth } = computeTiming(tasks, deps)
  const total = names.length === 0 ? 0 : Math.max(...names.map((n) => finish.get(n)))

  const lines = []
  if (mode === 'waves') {
    const maxDepth = names.length === 0 ? -1 : Math.max(...names.map((n) => depth.get(n)))
    for (let k = 0; k <= maxDepth; k++) {
      const wave = names.filter((n) => depth.get(n) === k)
      lines.push(`wave ${k}: ${wave.join(' ')}`)
    }
  } else {
    for (const n of names) {
      lines.push(`${n} start=${start.get(n)} finish=${finish.get(n)} depth=${depth.get(n)}`)
    }
  }
  lines.push(`total ${total}`)
  process.stdout.write(lines.join('\n') + '\n')
}

main()
"}

