  const state = { currentTable: root, currentPath: '' }

  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    const raw = lines[idx]

    let i = 0
    while (i < raw.length && (raw[i] === ' ' || raw[i] === '\t')) i++
    if (i >= raw.length) continue // blank line
    const first = raw[i]
    if (first === '#' || first === ';') continue // comment-only line

    try {
      parseLine(root, state, raw, i, first)
    } catch (e) {
      if (e instanceof ParseError && e.line === undefined) e.line = lineNo
      throw e
    }
