function compareCodePoint(a, b) {
  const an = Array.from(a, (ch) => ch.codePointAt(0))
  const bn = Array.from(b, (ch) => ch.codePointAt(0))
  const len = Math.min(an.length, bn.length)
  for (let i = 0; i < len; i++) {
    if (an[i] !== bn[i]) return an[i] - bn[i]
  }
  return an.length - bn.length
}

function sortedKeys(table) {
  return [...table.map.keys()].sort(compareCodePoint)
}

function items(node) {
  return node.items
}

/** Renders the document as indented JSON, sorting object keys. */
export function renderJSON(root) {
  return toJSON(root, '') + '\n'
}

function toJSON(node, indent) {
  const childIndent = indent + '  '
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const lines = keys.map(
        (k) => `${childIndent}${JSON.stringify(k)}: ${toJSON(node.map.get(k), childIndent)}`
      )
      return `{\n${lines.join(',\n')}\n${indent}}`
    }
    case 'aot':
    case 'array': {
      const list = items(node)
      if (list.length === 0) return '[]'
      const lines = list.map((it) => `${childIndent}${toJSON(it, childIndent)}`)
      return `[\n${lines.join(',\n')}\n${indent}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
      return node.value.toString()
    case 'float':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      throw new Error(`unreachable node kind ${node.kind}`)
  }
}

function typeName(node) {
  return node.kind === 'aot' ? 'array' : node.kind
}

/** Renders one `<path> <type>` line per node below the root, depth first. */
export function renderKeys(root) {
  const lines = []
  walkKeys(root, '', lines)
  return lines.map((l) => l + '\n').join('')
}

function walkKeys(node, path, lines) {
  if (node.kind === 'table') {
    for (const k of sortedKeys(node)) {
      const child = node.map.get(k)
      const childPath = path === '' ? k : `${path}.${k}`
      lines.push(`${childPath} ${typeName(child)}`)
      walkKeys(child, childPath, lines)
    }
  } else if (node.kind === 'aot' || node.kind === 'array') {
    items(node).forEach((child, i) => {
      const childPath = `${path}[${i}]`
      lines.push(`${childPath} ${typeName(child)}`)
      walkKeys(child, childPath, lines)
    })
  }
}
"}

