/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'node:fs'
import { parseDocument } from './parser.js'
import { renderJSON, renderKeys } from './render.js'
import { ParseError } from './parse-error.js'

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

const mode = process.argv[2]
if (mode !== 'json' && mode !== 'keys') {
  fail('error: usage: cli.js json|keys')
}

let input
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

try {
  const root = parseDocument(input)
  process.stdout.write(mode === 'json' ? renderJSON(root) : renderKeys(root))
  process.exit(0)
} catch (e) {
  if (e instanceof ParseError) {
    fail(`error: line ${e.line}: ${e.reason}`)
  }
  throw e
}
"}

